import com.comsol.model.*;
import com.comsol.model.util.*;

public class Bar {
  public static void main(String[] args) throws Exception {
    Model model = ModelUtil.create("Model");
    model.param().set("L", "1[m]");
    model.component().create("comp1", true);
    model.component("comp1").geom().create("geom1", 3);
    model.component("comp1").geom("geom1").create("blk1", "Block");
    model.component("comp1").geom("geom1").feature("blk1").set("size", new String[]{"L","0.1","0.1"});
    model.component("comp1").geom("geom1").run();
    model.component("comp1").physics().create("ht", "HeatTransfer", "geom1");
    model.component("comp1").mesh().create("mesh1");
    model.component("comp1").mesh("mesh1").autoMeshSize(4);
    model.component("comp1").mesh("mesh1").run();
    model.study().create("std1");
    model.study("std1").create("stat", "Stationary");
    model.sol().createAutoSequence("std1");
    model.study("std1").run();
    model.save("bar_solved.mph");
    ModelUtil.remove("Model");
  }
}

mphstart(2036);
import com.comsol.model.util.*
model = mphload('busbar.mph');
for V = [10 20 30]
    model.param.set('Vtot', sprintf('%d[mV]', V));
    model.study('std1').run();
    Tmax = mphmax(model, 'T', 'volume');
    fprintf('V = %d mV -> Tmax = %.2f K\n', V, Tmax);
end
mphplot(model, 'pg1', 'rangenum', 1);
mphsave(model, 'busbar_sweep.mph');
ModelUtil.remove('Model');

// Model Method: sweep a parameter and collect the maximum temperature
double[] widths = {0.01, 0.02, 0.03};
for (double w : widths) {
  model.param().set("w", w + "[m]");
  model.study("std1").run();
  double Tmax = model.result().numerical("max1").getReal()[0][0];
  message("w = " + w + " m, Tmax = " + Tmax + " K");
}

